def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        """Helper function to calculate the sum of proper divisors of n."""
        divisors = [1]  # 1 is a proper divisor of any positive integer > 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:  # Avoid adding the square root twice for perfect squares
                    divisors.append(n // i)
        return sum(divisors)

    def is_amicable(a):
        """Check if a number is amicable."""
        b = sum_of_divisors(a)
        return b != a and sum_of_divisors(b) == a

    # Calculate the sum of all amicable numbers under the given limit
    amicable_sum = 0
    for num in range(2, limit):
        if is_amicable(num):
            amicable_sum += num

    return amicable_sum

# Example usage
assert amicable_numbers_sum(999) == 504
