def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the last dictionary in the order takes precedence.
    """
    # Create a new dictionary and update it sequentially with each dictionary
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)
    return merged_dict

